import{_ as a,o as s,c as e,a8 as p}from"./chunks/framework.DQoZbSQ3.js";const m=JSON.parse('{"title":"为什么 Token 消耗这么快？","description":"","frontmatter":{"title":"为什么 Token 消耗这么快？","date":"2026-05-18T00:00:00.000Z","category":"常见问题","tags":["Token","计费","成本"]},"headers":[],"relativePath":"faq/token-consumption-high.md","filePath":"faq/token-consumption-high.md","lastUpdated":1779089963000}'),l={name:"faq/token-consumption-high.md"};function t(i,n,o,r,c,u){return s(),e("div",null,[...n[0]||(n[0]=[p(`<h2 id="关键认知-你看到的-模型处理的" tabindex="-1">关键认知：你看到的 ≠ 模型处理的 <a class="header-anchor" href="#关键认知-你看到的-模型处理的" aria-label="Permalink to &quot;关键认知：你看到的 ≠ 模型处理的&quot;">​</a></h2><p>用户发了一句&quot;帮我写段代码&quot;，但模型实际处理的内容远不止这句话。</p><p><strong>每次调用实际消耗的 Token 包括：</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>系统 Prompt（每次都计费）</span></span>
<span class="line"><span>  +</span></span>
<span class="line"><span>全部历史消息（第1轮到现在）</span></span>
<span class="line"><span>  +</span></span>
<span class="line"><span>本次用户输入</span></span>
<span class="line"><span>  +</span></span>
<span class="line"><span>模型输出内容</span></span>
<span class="line"><span>  +</span></span>
<span class="line"><span>Tool Call 内容（如有）</span></span>
<span class="line"><span>= 实际计费 Token</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="典型翻倍场景" tabindex="-1">典型翻倍场景 <a class="header-anchor" href="#典型翻倍场景" aria-label="Permalink to &quot;典型翻倍场景&quot;">​</a></h2><p><strong>场景一：长系统 Prompt</strong> 有些客户端预置了几千字的系统提示词，每次对话都带上，你完全没感知。</p><p><strong>场景二：全量历史消息</strong> 聊了 50 轮的对话，第 51 轮发送时，前 50 轮全部打包发给模型，Token 是累加的。</p><p><strong>场景三：图片输入</strong> 一张 1080p 图片约等于 1000-2000 个文本 Token，分辨率越高越贵。</p><p><strong>场景四：工具调用</strong> Function Calling 的 schema 定义和工具返回结果都计入 Token。</p><h2 id="降低消耗的方法" tabindex="-1">降低消耗的方法 <a class="header-anchor" href="#降低消耗的方法" aria-label="Permalink to &quot;降低消耗的方法&quot;">​</a></h2><ul><li>定期开新对话，不要在一个对话里聊几十轮</li><li>缩短或简化系统 Prompt</li><li>压缩图片分辨率后再上传</li><li>选用轻量模型处理简单任务（DeepSeek、Claude Haiku）</li><li>使用 Prompt Caching（适合固定系统 Prompt 的场景）</li></ul>`,11)])])}const h=a(l,[["render",t]]);export{m as __pageData,h as default};
